{
  "task": "Differentiate diagnoses based on airspace consolidation patterns and distribution in chest radiographs",
  "anatomy": "Thorax, lungs, mediastinum",
  "option_differences": [
    {
      "attribute": "spatial distribution and morphology of consolidations",
      "question": "Are the consolidations peripheral, upper-lobe predominant, and migratory (suggesting chronic eosinophilic pneumonia) vs. lower-lobe/centrilobular with volume loss or fibrosis (e.g., lipoid pneumonia, lymphoma, or lepidic adenocarcinoma)?",
      "option_labels": ["A", "B"],
      "image_ids": ["image:1"]
    },
    {
      "attribute": "presence of hilar/mediastinal lymphadenopathy and parenchymal mass-like opacity vs. diffuse reticulonodular or ground-glass pattern",
      "question": "Is there a dominant unilateral mass-like consolidation with minimal lymphadenopathy (suggesting primary pulmonary lymphoma or lepidic adenocarcinoma) versus symmetric bilateral hilar lymphadenopathy with parenchymal nodules (sarcoidosis)?",
      "option_labels": ["C", "D"],
      "image_ids": ["image:1", "image:2"]
    }
  ],
  "missing_attributes": ["clinical history (e.g., exposure, symptoms duration, eosinophilia)", "temporal evolution (no timepoint resolved)", "lateral view clarity for volume loss/fibrosis", "CT correlation"],
  "recommended_view": "compare",
  "uncertain": true
}
